public class StoreUtils {

    public static <K, V extends Comparable<V>> K keyOfMax(TypedStore<K, V> store) {
        K best = null;
        V bestValue = null;
        for (K key : store.keys()) {
            V value = store.get(key);
            if (bestValue == null || value.compareTo(bestValue) > 0) {
                best = key;
                bestValue = value;
            }
        }
        return best;
    }

    public static <K, V extends Number> double sumValues(TypedStore<K, V> store) {
        double total = 0.0;
        for (V value : store.values()) {
            total += value.doubleValue();
        }
        return total;
    }

    public static <K, V> void copyAll(TypedStore<K, ? extends V> source, TypedStore<K, V> dest) {
        for (K key : source.keys()) {
            dest.put(key, source.get(key));
        }
    }
}

