public class StoreUtilsTest {
    static int failures = 0;

    static void check(String label, Object expected, Object actual) {
        if (java.util.Objects.equals(expected, actual)) {
            System.out.println("PASS  " + label);
        } else {
            System.out.println("FAIL  " + label + " -- expected " + expected + " but got " + actual);
            failures++;
        }
    }

    public static void main(String[] args) {
        TypedStore<String, Integer> ages = new TypedStore<>();
        ages.put("ana", 31);
        ages.put("bo", 44);
        ages.put("cy", 44);

        check("size", 3, ages.size());
        check("get an existing key", Integer.valueOf(31), ages.get("ana"));
        check("get a missing key", null, ages.get("zed"));
        check("getOrDefault falls back", Integer.valueOf(-1), ages.getOrDefault("zed", -1));
        check("containsKey", true, ages.containsKey("bo"));
        check("keys keep insertion order", "[ana, bo, cy]", String.valueOf(ages.keys()));

        ages.put("ana", 32);
        check("replacing a value keeps the key order", "[ana, bo, cy]", String.valueOf(ages.keys()));
        check("replacing a value updates it", Integer.valueOf(32), ages.get("ana"));

        String rejected = "no exception";
        try {
            ages.put(null, 1);
        } catch (IllegalArgumentException e) {
            rejected = "IllegalArgumentException";
        } catch (RuntimeException e) {
            rejected = e.getClass().getSimpleName();
        }
        check("a null key is rejected", "IllegalArgumentException", rejected);

        check("keyOfMax picks the earliest of equal values", "bo", StoreUtils.keyOfMax(ages));
        check("keyOfMax on an empty store", null,
              StoreUtils.keyOfMax(new TypedStore<String, Integer>()));
        check("sumValues", 120.0, StoreUtils.sumValues(ages));

        TypedStore<String, Integer> whole = new TypedStore<>();
        whole.put("one", 1);
        TypedStore<String, Number> mixed = new TypedStore<>();
        mixed.put("half", 0.5);
        StoreUtils.copyAll(whole, mixed);
        check("copyAll widened the value type", 2, mixed.size());
        check("copyAll copied the entry", "1", String.valueOf(mixed.get("one")));

        TypedStore<String, String> words = new TypedStore<>();
        words.put("a", "apple");
        words.put("b", "pear");
        check("keyOfMax works for any Comparable", "b", StoreUtils.keyOfMax(words));

        if (failures > 0) {
            System.out.println(failures + " test(s) failed.");
            System.exit(1);
        }
        System.out.println("ALL TESTS PASSED");
    }
}

